function neighborView(){const row=list(A().neighbors?.rows).find(r=>r.source_id===state.neighborSource);if(!row)return '<p class="empty">No neighbor result is supplied for this source.</p>';const k=A().neighbors?.k,cols=[['Lexical',list(row.lexical_ids)],['Semantic',list(row.semantic_ids)],['Centered-window semantic',list(row.window_ids)]];return `<p class="caption">${inspect('source',row.source_id,doc(row.source_id)?.title||row.source_id)} · k=${num(k)}. Whole-text lexical/semantic neighbor Jaccard: <strong id="neighbor-jaccard">${num(row.jaccard,3)}</strong>${finite(row.window_jaccard)?` · semantic whole/window Jaccard: ${num(row.window_jaccard,3)}`:''}.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Neighbor comparison"><table class="comparison-table"><thead><tr><th>Rank</th>${cols.map(([name])=>`<th>${esc(name)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:Math.max(...cols.map(([,ids])=>ids.length),0)},(_,i)=>`<tr><th scope="row">${i+1}</th>${cols.map(([,ids])=>`<td>${ids[i]?inspect('source',ids[i],doc(ids[i])?.title||ids[i]):'Not available'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function clusterView(){const c=A().clusters||{};return `<h3>Cluster diagnostics</h3><div class="split-detail">${['lexical','semantic'].map(key=>{const x=c[key]||{},runs=list(x.runs);return `<div class="diagnostic"><h3>${human(key)} grouping</h3><p>${esc(text(x.selection||x.scope||x.status||'Unreported'))}</p><p class="caption">k=${num(x.k)} · ${esc(x.algorithm||'Algorithm unreported')}</p><div class="table-wrap" tabindex="0" role="region" aria-label="${esc(key)} cluster seed diagnostics"><table><thead><tr><th>Seed</th><th>Silhouette</th><th>Medium ARI</th><th>Text-origin ARI</th></tr></thead><tbody>${runs.map(r=>`<tr><th scope="row">${num(r.seed)}</th><td class="numeric">${num(r.cosine_silhouette,4)}</td><td class="numeric">${num(r.medium_adjusted_rand,4)}</td><td class="numeric">${num(r.text_origin_adjusted_rand,4)}</td></tr>`).join('')||'<tr><td colspan="4">No seed results supplied.</td></tr>'}</tbody></table></div><p class="caption">Seed-pair adjusted Rand: ${list(x.seed_pair_adjusted_rand).map(r=>`${r.left}/${r.right}: ${num(r.value,3)}`).join(' · ')||'Unreported'}.</p></div>`;}).join('')}</div><p class="analysis-note">Cluster labels are model partitions, not verified doctrines. Silhouette describes separation under the chosen metric; adjusted Rand index (ARI) describes partition agreement with metadata, not classification accuracy. Seed differences expose sensitivity rather than establishing an optimal category count.</p>`;}
function topicView(){const t=A().topics||{},components=list(t.components),rows=list(t.weights);if(!components.length)return '';return `<h3>Exploratory topic factors</h3><p class="analysis-note">${esc(t.selection)} Nonnegative matrix factorization (NMF) decomposes lexical features. Row-normalized weights below are relative factor loadings, not probabilities of beliefs, proportions of speaking time or validated topic prevalence. Repeated editorial language and remaining name variants can dominate a factor.</p><div class="topic-key">${components.map((c,i)=>`<div><h4><span class="topic-swatch" style="background:${palette[i]}"></span>Factor ${num(c.id)}</h4><p>${esc(list(c.terms).join(' · '))}</p></div>`).join('')}</div><details><summary>Inspect all ${num(rows.length)} source-factor profiles</summary><div class="table-wrap" tabindex="0" role="region" aria-label="NMF source-factor profiles"><table class="source-table"><thead><tr><th>Source edition</th><th>Relative factor loadings</th>${components.map(c=>`<th>Factor ${num(c.id)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${inspect('source',r.source_id,doc(r.source_id)?.title||r.source_id)}<small>${esc(medium(doc(r.source_id)))}</small></th><td><div class="factor-bar" aria-label="${esc(list(r.weights).map((v,i)=>`Factor ${i+1}: ${num(v,3)}`).join('; '))}">${list(r.weights).map((v,i)=>`<span style="width:${Math.max(0,Math.min(1,v))*100}%;background:${palette[i]}"></span>`).join('')}</div></td>${list(r.weights).map(v=>`<td class="numeric">${num(v,3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function pairSummaryView(){const rows=list(A().pair_summary);return `<h3>Source labels versus medium context</h3><p class="analysis-note">The same printed or comparison label does not authenticate a shared speaker. Pair observations share documents and are statistically dependent; these descriptive means are not significance tests.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Pair category means"><table class="comparison-table"><thead><tr><th>Pair category</th><th>Pairs</th><th>Lexical mean</th><th>Semantic mean</th><th>300-token lexical</th><th>300-token semantic</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(human(r.kind))}</th><td>${num(r.pairs)}</td><td>${num(r.lexical_cosine,4)}</td><td>${num(r.semantic_cosine,4)}</td><td>${num(r.window_lexical_cosine,4)}</td><td>${num(r.window_semantic_cosine,4)}</td></tr>`).join('')}</tbody></table></div>`;}
function controlView(){const c=A().synthetic_controls;if(!c)return '';const statements=list(c.statements);return `<details><summary>Constructed stress test: why high cosine cannot label agreement</summary><div class="notice"><p><strong>Synthetic diagnostic — excluded from every corpus count.</strong> ${esc(c.scope||'These statements were constructed to inspect model behavior; they are not observed source claims.')}</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Synthetic polarity stress cases"><table class="comparison-table"><thead><tr><th>Constructed statement</th><th>Comparison statement</th><th>Intended test</th><th>Semantic cosine</th></tr></thead><tbody>${list(c.pairs).map(r=>`<tr><th scope="row">${esc(statements.find(x=>x.id===r.left)?.text||r.left)}</th><td>${esc(statements.find(x=>x.id===r.right)?.text||r.right)}</td><td>${esc(human(r.intended_relation))}</td><td class="numeric">${num(r.semantic_cosine,4)}</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">An explicit negation may score above an approximate paraphrase. This illustrates a failure mode; five constructed cases do not estimate a real-world error rate.</p></details>`;}
