function contextualTermsView(){const a=state.modules.contextual_terms;if(!a)return `<h3>Contextual token representations</h3>${unavailable('contextual_terms','The separate contextual-token analysis')}`;state.contextualTerm ||= list(a.terms)[0]?.term;return `<h3>Words in context: a separate token-state experiment</h3><div class="notice"><p><strong>Exploratory token states, not validated word senses or a belief ontology.</strong> This section extracts target subword states from the pinned sentence model. It is distinct from the lexical TF-IDF heatmap and from whole-document embeddings. Similarity depends on the sampled source contexts.</p></div><p class="analysis-note">${esc(text(a.scope))}</p><p class="caption">${num(a.coverage?.terms)} selected terms · ${num(a.coverage?.source_editions)} source editions · ${num(a.coverage?.source_term_pairs)} source/term pairs · ${num(a.coverage?.sampled_occurrences)} sampled occurrences.</p><div class="controls"><label>Term and source-context overlay<select id="contextual-term">${opt(list(a.terms).map(x=>x.term),state.contextualTerm,x=>x)}</select></label></div><div id="contextual-results">${contextualTermResults(a)}</div><details><summary>Token-state projection and cluster diagnostics</summary><p class="analysis-note">${esc(text(a.selection))}</p><p class="analysis-note">${esc(text(a.projection))}</p><div class="table-wrap" tabindex="0" role="region" aria-label="Contextual term cluster seed diagnostics"><table><thead><tr><th>Seed</th><th>Cosine silhouette</th></tr></thead><tbody>${list(a.clusters?.runs).map(r=>`<tr><th scope="row">${num(r.seed)}</th><td>${num(r.cosine_silhouette,4)}</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">Seed-pair adjusted Rand: ${esc(text(a.clusters?.seed_pair_adjusted_rand))}. Partitions are exploratory diagnostics, not verified semantic categories.</p><ul>${list(a.limitations).map(x=>`<li>${esc(text(x))}</li>`).join('')}</ul></details>${figuresView(a)}<div class="downloads"><a href="${esc(moduleFile('contextual_terms'))}" download>Contextual-token coordinates, coverage and similarities</a></div>`;}
function contextualTermResults(a){const terms=list(a.terms),contexts=list(a.source_contexts),term=terms.find(x=>x.term===state.contextualTerm);if(!term)return '<p class="empty">No term record supplied.</p>';const selected=contexts.filter(x=>x.term===term.term),all=[...terms,...contexts],xs=all.map(x=>x.x).filter(finite),ys=all.map(x=>x.y).filter(finite),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),sx=x=>45+510*(x-xmin)/(xmax-xmin||1),sy=y=>335-275*(y-ymin)/(ymax-ymin||1),media=unique(documents().map(medium)).sort(),colors=id=>palette[media.indexOf(medium(source(id)))%palette.length]||palette[0];const usedLabels=[];const termLabel=t=>{const px=sx(t.x),py=sy(t.y),w=t.term.length*6.4+3;let pos;for(const [dx,dy] of [[8,-7],[8,16],[-w-8,-7],[-w-8,16],[5,-24],[5,32],[-w-8,-24],[-w-8,32],[18,-42],[-w-18,42],[32,6],[-w-32,6]]){const x=Math.max(40,Math.min(570-w,px+dx)),y=Math.max(40,Math.min(340,py+dy)),b={x,y:y-12,w,h:15};if(!usedLabels.some(z=>b.x<z.x+z.w&&b.x+b.w>z.x&&b.y<z.y+z.h&&b.y+b.h>z.y)&&![...terms,...selected].some(z=>sx(z.x)+7>b.x&&sx(z.x)-7<b.x+b.w&&sy(z.y)+7>b.y&&sy(z.y)-7<b.y+b.h)){pos={x,y,b};break;}}pos ||= {x:px+8,y:py-7,b:{x:px+8,y:py-19,w,h:15}};usedLabels.push(pos.b);return `${Math.hypot(pos.x-px,pos.y-py)>20?`<line class="plot-arrow" x1="${px}" y1="${py}" x2="${Math.max(pos.b.x,Math.min(pos.b.x+pos.b.w,px))}" y2="${Math.max(pos.b.y,Math.min(pos.b.y+pos.b.h,py))}"/>`:''}<text class="plot-label" x="${pos.x}" y="${pos.y}">${esc(t.term)}</text>`;};const index=terms.indexOf(term),neighbors=terms.map((x,i)=>({...x,cosine:a.term_cosine_matrix?.[index]?.[i]})).filter(x=>x.term!==term.term).sort((x,y)=>y.cosine-x.cosine||x.term.localeCompare(y.term)).slice(0,5);return `<p class="analysis-note"><strong>${esc(term.term)}</strong> appears in ${num(term.document_frequency)} retained source editions. Diamonds represent source-balanced term centroids; colored circles show sampled source means for this term. All use the same PCA transform and stable display bounds. Lines indicate provenance to the term centroid, not an inferential effect. Vectors are normalized after each mean, so a term centroid need not sit at the arithmetic center of its displayed source points.</p><div class="plot-shell"><div class="plot-scroll" tabindex="0" role="region" aria-label="Contextual term centroid and source overlays"><svg class="contextual-projection" viewBox="0 0 600 390"><path class="plot-axis" d="M35 30V350H575"/>${selected.map(x=>`<line class="plot-arrow" x1="${sx(term.x)}" y1="${sy(term.y)}" x2="${sx(x.x)}" y2="${sy(x.y)}"/>`).join('')}${terms.map(x=>`<g tabindex="0" role="button" data-context-term="${esc(x.term)}" aria-label="Select contextual term ${esc(x.term)}"><path d="M${sx(x.x)} ${sy(x.y)-6}l6 6-6 6-6-6Z" fill="${x.term===term.term?'#203d35':'#98aa9a'}" stroke="#fffef9"/>${termLabel(x)}</g>`).join('')}${selected.map(x=>`<circle tabindex="0" role="button" data-context-source="${esc(x.source_id)}" data-inspect-kind="source" data-inspect-id="${esc(x.source_id)}" aria-label="Inspect source context: ${esc(source(x.source_id)?.title||x.source_id)}" cx="${sx(x.x)}" cy="${sy(x.y)}" r="5" fill="${colors(x.source_id)}" stroke="#fffef9"><title>${esc(medium(source(x.source_id)))}: ${esc(source(x.source_id)?.title||x.source_id)} · ${num(x.sampled_occurrences)} sampled of ${num(x.occurrences_available)} occurrences</title></circle>`).join('')}<path d="M${sx(term.x)} ${sy(term.y)-7}l7 7-7 7-7-7Z" fill="#203d35" stroke="#fffef9" stroke-width="1.5"><title>Selected term centroid: ${esc(term.term)}</title></path><text class="plot-key" x="40" y="378">Shared PCA display; original embedding cosine is reported in the tables</text></svg></div><div class="legend">${unique(selected.map(x=>medium(source(x.source_id)))).sort().map(m=>`<span><i style="background:${palette[media.indexOf(m)%palette.length]}"></i>${esc(m)}</span>`).join('')}</div></div><div class="split-detail"><div><h3>Nearest selected term centroids</h3><p class="analysis-note">Original-dimensional cosine, not distance read from the lossy two-dimensional plot.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Nearest contextual term centroids"><table><thead><tr><th>Term</th><th>Cosine</th><th>Source editions</th></tr></thead><tbody>${neighbors.map(x=>`<tr><th scope="row"><button type="button" class="text-button" data-context-term="${esc(x.term)}">${esc(x.term)}</button></th><td>${num(x.cosine,4)}</td><td>${num(x.document_frequency)}</td></tr>`).join('')}</tbody></table></div></div><div><h3>Source contexts contributing to this term</h3><p class="analysis-note">Each source contributes a sampled mean, then sources receive equal weight in the term centroid. Full context text remains private.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Contextual term source sampling"><table class="context-table"><thead><tr><th>Source context</th><th>Sampled / available occurrences</th><th>Cosine to term centroid</th></tr></thead><tbody>${selected.map(x=>`<tr><th scope="row">${inspect('source',x.source_id,source(x.source_id)?.title||x.source_id)}</th><td>${num(x.sampled_occurrences)} / ${num(x.occurrences_available)}</td><td>${num(x.cosine_to_term_centroid,4)}</td></tr>`).join('')}</tbody></table></div></div></div>`;}
function pairRows(){const rows=list(A().pairs);return [...rows].sort((a,b)=>{const metric=r=>state.matrixMode==='difference'?Math.abs(r.semantic_cosine-r.lexical_cosine):state.matrixMode==='lexical'?r.lexical_cosine:r.semantic_cosine;return metric(b)-metric(a)||String(a.source).localeCompare(String(b.source));});}
function pairView(){const rows=pairRows();return `<p class="caption">${num(rows.length)} unordered pairs; showing 20 by the selected ordering. Scores are not calibrated to the same distribution, and a score difference is a descriptive model comparison.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Lexical and semantic pair scores"><table class="comparison-table"><thead><tr><th>First source</th><th>Second source</th><th>Lexical cosine</th><th>Semantic cosine</th><th>Source relationship</th></tr></thead><tbody>${rows.slice(0,20).map(r=>`<tr><th scope="row">${inspect('source',r.source,doc(r.source)?.title||r.source)}</th><td>${inspect('source',r.target,doc(r.target)?.title||r.target)}</td><td class="numeric">${num(r.lexical_cosine,4)}</td><td class="numeric">${num(r.semantic_cosine,4)}</td><td>${r.same_medium?'Same':'Different'} medium context<small>${r.same_label?'Same':'Different'} comparison label · not entity identity</small></td></tr>`).join('')}</tbody></table></div>`;}
const figureCaptions={
  'representation-maps':'The same 25 source editions in separate lexical and neural spaces. The neural display is oriented with orthogonal Procrustes alignment only. Low-dimensional distances are lossy and do not measure agreement or entity identity.',
  'lexical-neural-pairs':'Lexical and neural cosine scores for 300 statistically dependent source pairs. Color distinguishes same-medium and different-medium contexts; proximity does not establish a shared proposition.',
  'neighbor-stability':'Top-five neighbor-set Jaccard across lexical/neural representations, whole/centered-window text and masked/unmasked names. This measures model stability, not answer-retrieval accuracy.',
  'term-source-overlay':'Observed unigram and bigram features, shown as mean document TF-IDF weights by medium context. These are lexical features, not neural word embeddings. Exact-phrase masking leaves some identity variants visible.',
  'source-label-contrast':'Descriptive pair means within the fixed 25-edition frame. Comparison labels and exact printed names are distinct; format, medium, date and length remain confounded. No inferential confidence intervals are implied.'
};
function figuresView(module=A()){const figures=list(module.figures),pngs=figures.filter(f=>/\.png$/.test(f.file||''));return `<div class="figure-grid">${pngs.map(f=>{const file=safeFile(f.file),path=file?.includes('/')?file:`figures/${file}`,stem=file?.replace(/\.png$/,''),caption=figureCaptions[stem]||f.alt||f.title||'Source-bound analytical figure.';if(!file)return '';return `<figure class="figure"><h3>${esc(f.title||human(stem))}</h3><a href="${esc(path)}" target="_blank" rel="noopener">Open full-size figure ↗</a><img src="${esc(path)}" alt="${esc(caption)}" loading="lazy"><figcaption>${esc(caption)}<div class="downloads">${figures.filter(x=>x.file?.replace(/\.(png|svg|pdf)$/,'')===stem).map(x=>{const s=safeFile(x.file);return s?`<a href="${esc(s.includes('/')?s:`figures/${s}`)}" download>${esc(s.split('.').at(-1).toUpperCase())}</a>`:'';}).join('')}</div></figcaption></figure>`;}).join('')||'<p class="empty">No rendered analytical figures are supplied in this module.</p>'}</div>`;}

function asrView(){const a=state.modules.asr;if(!a)return unavailable('asr','The speech-recognition benchmark');const summary=a.summary||{},models=[[a.baseline,a.baseline_performance,'Controlled baseline'],[a.model,a.upgraded_performance,'Larger model']];state.asrContext ||= 'all';return `<div class="notice"><p><strong>Transcript disagreement is not transcription error.</strong> No checked reference transcript is available, so this experiment cannot report WER, word accuracy or a verified improvement. Isolated windows are not complete recording transcripts.</p></div><p class="analysis-note">${esc(text(a.scope))}</p><div class="metric-strip"><div class="metric"><strong>${num(summary.recordings)}</strong><span>Original recordings sampled</span><small>${num(summary.source_contexts)} source contexts</small></div><div class="metric"><strong>${num(summary.paired_windows)}</strong><span>Paired 30-second windows</span><small>${num(summary.model_window_inferences)} model inferences</small></div><div class="metric"><strong>${num(summary.unique_audio_seconds/60,2)}</strong><span>Unique audio minutes sampled</span><small>Same PCM for both recognizers</small></div><div class="metric"><strong>${num(summary.median_symmetric_normalized_word_edit_distance,3)}</strong><span>Median normalized edit disagreement</span><small>No accuracy inference</small></div></div><p class="caption">Mean normalized edit disagreement: ${num(summary.mean_symmetric_normalized_word_edit_distance,3)}. Both mean and median include every selected window.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Speech model execution"><table class="source-table"><thead><tr><th>Model / actual representation</th><th>Workers / CPU threads each</th><th>Median inference RTF</th><th>Outer stage wall time</th><th>Actual inference overlap</th><th>Peak worker RSS</th></tr></thead><tbody>${models.filter(([m])=>m).map(([m,p,name])=>`<tr><th scope="row">${m.model_card_url?external(m.model_card_url,m.id):esc(m.id)}<small>${esc(name)} · ${esc(m.device)} · ${esc(m.compute_type)}</small><span class="hash">${esc(m.revision||'Hub revision unrecorded; checkpoint files hash-bound in JSON')}</span></th><td>${num(p?.workers)} / ${num(p?.cpu_threads_per_worker)}</td><td>${num(p?.median_real_time_factor,4)}</td><td>${num(p?.outer_stage_wall_seconds,2)} s</td><td>${num(p?.actual_inference_overlap_seconds,2)} s</td><td>${num(p?.max_worker_rss_kib/1048576,2)} GiB</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">RTF is inference seconds divided by audio seconds. Each model ran with two one-thread workers; the table reports observed stage time and overlap, not a matched serial-versus-parallel speedup. Architectures, precision and decoding differ. ${num(summary.windows_with_negation_count_difference)} windows have different negation-cue counts; those cues do not establish a change of proposition.</p>${asrTriageView(a)}<div class="controls"><label>Audio source context<select id="asr-context">${filterOpts(unique(list(a.clips).map(x=>x.context)),state.asrContext,'All sampled contexts',x=>x)}</select></label></div><div id="asr-window-results">${asrWindowsView(a)}</div><details><summary>Recognition protocol and limitations</summary><p class="analysis-note">${esc(text(a.selection_rule))}</p><p class="analysis-note">${esc(text(a.measurement))}</p><p class="analysis-note">${esc(text(a.hardware))}</p><p class="analysis-note">${esc(a.model?.runtime_storage||'Model storage status unreported.')}</p><p class="analysis-note">${num(summary.baseline_windows_with_timestamp_overrun)} baseline windows contain unverified segment-end timestamps beyond their 30-second PCM boundary; maximum overrun ${num(summary.baseline_max_timestamp_overrun_seconds,2)} seconds. These are model timestamps, not evidence of audio outside the supplied window.</p><ul>${list(a.limitations).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="downloads"><a href="${esc(moduleFile('asr'))}" download>Download complete benchmark JSON and hashes</a></div>`;}
function asrTriageView(a){const r=a.posthoc_repetition_diagnostic;if(!r)return '';return `<div class="notice"><p><strong>Post-hoc text-quality triage: ${num(list(r.flagged_windows).length)} of ${num(a.clips?.length)} windows flagged.</strong> ${esc(r.rule)}</p>${list(r.flagged_windows).map(x=>`<p>${esc(x.context)} · ${esc(x.clip_id)}: longest identical-token run ${num(x.baseline_longest_identical_token_run)} in tiny.en versus ${num(x.upgraded_longest_identical_token_run)} in Parakeet.</p>`).join('')}<p>${esc(r.interpretation)} ${esc(r.scope)}</p></div>`;}
function asrWindowsView(a){const rows=list(a.clips).filter(x=>state.asrContext==='all'||x.context===state.asrContext);return `<p class="caption">Showing ${num(rows.length)} of ${num(list(a.clips).length)} paired windows; filters do not change the benchmark denominator.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Paired speech-recognition windows"><table class="source-table"><thead><tr><th>Window / context / source</th><th>Audio seconds</th><th>Words: tiny.en / Parakeet</th><th>RTF: tiny.en / Parakeet</th><th>Normalized edit disagreement</th><th>Token-set Jaccard</th><th>Negation cues: tiny.en / Parakeet</th><th>Longest repeated-token run: tiny.en / Parakeet</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.clip_id)}<small>${esc(r.context)}</small><small>${external(r.source_url,r.title)}</small></th><td>${num(r.start_seconds)}–${num(r.end_seconds)}</td><td>${num(r.baseline_words)} / ${num(r.upgraded_words)}</td><td>${num(r.baseline_real_time_factor,3)} / ${num(r.upgraded_real_time_factor,3)}</td><td><span class="measure-bar" style="--value:${Math.min(100,Math.max(0,r.symmetric_normalized_word_edit_distance*100))}%">${num(r.symmetric_normalized_word_edit_distance,3)}</span></td><td>${num(r.token_set_jaccard,3)}</td><td>${num(r.baseline_negation_cues)} / ${num(r.upgraded_negation_cues)}</td><td>${num(r.baseline_longest_identical_token_run)} / ${num(r.upgraded_longest_identical_token_run)}</td></tr>`).join('')}</tbody></table></div>`;}
function fullAsrView(){const a=state.modules.full_asr;if(!a)return `<h3>Separate full-recording transcription edition</h3>${unavailable('full_asr','The full-recording execution module')}`;const s=a.summary||{},p=a.performance||{};return `<h3>Separate full-recording transcription edition</h3><p class="analysis-note">${esc(text(a.scope))}</p>${badge(a.status)}<div class="metric-strip"><div class="metric"><strong>${num(s.recordings)}</strong><span>Complete retained recordings reprocessed</span><small>${num(s.new_audio_downloads)} new audio downloads</small></div><div class="metric"><strong>${num(s.covered_audio_seconds/60,2)}</strong><span>Minutes of original decoded input</span><small>${num(s.covered_samples)} samples</small></div><div class="metric"><strong>${num(s.chunks)}</strong><span>Independent recognition windows</span><small>Final partial tails included</small></div><div class="metric"><strong>${num(s.new_words)}</strong><span>Words in the new machine-text edition</span><small>${num(s.old_words)} words in old editions</small></div></div><div class="notice"><p><strong>Complete input coverage is separate from transcription accuracy.</strong> Every supplied sample is covered by the partition, but the recognizer uses independent windows and may lose cross-window context. Window records are not verified utterance boundaries or speaker turns. Original editions and their existing annotations remain preserved. ${num(s.empty_text_chunks)} windows produced empty text and remain counted; silence versus missed speech has not been checked against a reference.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Complete recording recognition coverage"><table class="source-table"><thead><tr><th>Recording / source context</th><th>Audio minutes</th><th>Windows / empty / last seconds</th><th>Words: old / new</th><th>Coverage / attribution</th></tr></thead><tbody>${list(a.documents).map(r=>`<tr><th scope="row">${external(r.source_url,r.title)}<small>${esc(r.medium)} · ${esc(r.claimed_label)}</small></th><td>${num(r.duration_seconds/60,2)}</td><td>${num(r.chunks)} / ${num(r.empty_text_chunks)} / ${num(r.last_chunk_seconds,3)}</td><td>${num(r.old_words)} / ${num(r.new_words)}</td><td>${esc(text(r.coverage))}<small>Speaker: ${esc(r.speaker_role)} · accuracy verified: ${esc(text(r.accuracy_verified))}</small></td></tr>`).join('')}</tbody></table></div><p class="analysis-note">Actual execution: ${num(p.workers)} workers × ${num(p.cpu_threads_per_worker)} CPU thread each; ${num(p.stage_wall_seconds/60,2)} minutes stage wall time, ${num(p.actual_inference_overlap_seconds/60,2)} minutes of overlapping inference, median chunk RTF ${num(p.median_chunk_real_time_factor,3)}. These are observed cloud timings, not a controlled parallel speedup estimate.</p><details><summary>Full-recognition protocol and limitations</summary><p class="analysis-note">${esc(text(a.protocol||a.recognition_protocol||a.method))}</p><ul>${list(a.limitations).map(x=>`<li>${esc(text(x))}</li>`).join('')}</ul></details><div class="downloads"><a href="${esc(moduleFile('full_asr'))}" download>Full-recording execution metadata</a></div>`;}
function asrSensitivityView(){const a=state.modules.asr_sensitivity;if(!a)return `<h3>Downstream sensitivity to recognizer edition</h3>${unavailable('asr_sensitivity','The recognizer-edition sensitivity analysis')}`;state.sensitivitySource ||= list(a.records)[0]?.source_id;const c=a.coverage||{},review=a.card_reannotation||{};return `<h3>Downstream sensitivity to recognizer edition</h3><p class="analysis-note">${esc(text(a.scope))}</p>${badge(a.status)}<div class="notice"><p><strong>A separate counterfactual index, with annotations still bound to the original edition.</strong> ${num(c.paired_recordings)} recording editions are replaced for this calculation; ${num(c.unchanged_source_editions)} source editions stay fixed. The original ${num(c.baseline_source_editions)}-edition dashboard remains the primary analysis. Different segmentation and recognition settings are confounded with the model change.</p><p>${num(review.affected_cards)} answer cards require re-reading before transfer to the new recognition edition. ${num(review.cards_rewritten)} cards have been rewritten in this sensitivity module. Changing the text alone does not validate an inherited answer or locator.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Paired whole-recording recognizer editions"><table class="source-table"><thead><tr><th>Same retained recording</th><th>Words: old / new</th><th>Normalized edit disagreement</th><th>Paired lexical / semantic cosine</th><th>Neighbor Jaccard: lexical / semantic</th><th>New lexical out-of-vocabulary occurrences</th></tr></thead><tbody>${list(a.records).map(r=>`<tr><th scope="row">${inspect('source',r.source_id,r.title||r.source_id)}<small>${esc(r.medium_name)}</small></th><td>${num(r.old_words)} / ${num(r.new_words)}</td><td>${num(r.normalized_token_disagreement,3)}</td><td>${num(r.paired_lexical_cosine,3)} / ${num(r.paired_semantic_cosine,3)}</td><td>${num(r.lexical_neighbor_jaccard,3)} / ${num(r.semantic_neighbor_jaccard,3)}</td><td>${num(r.new_lexical_oov_occurrences)} / ${num(r.new_lexical_term_occurrences)}</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">Model words: ${num(c.baseline_words)} in the original frame and ${num(c.counterfactual_words)} in this counterfactual frame. All scores compare machine outputs; they do not measure transcription or answer accuracy. Source IDs remain stable solely to compare the same recording across editions.</p><div class="controls"><label>Inspect neighbor changes for any source<select id="sensitivity-source">${opt(list(a.source_ids),state.sensitivitySource,id=>source(id)?.title||id)}</select></label></div><div id="sensitivity-neighbors">${sensitivityNeighborView(a)}</div><details><summary>Cards requiring new-edition reannotation</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Source cards requiring reannotation"><table><thead><tr><th>Original answer card</th><th>Question</th><th>Edition transfer status</th></tr></thead><tbody>${list(review.records).map(r=>`<tr><th scope="row">${inspect('card',r.card_id,r.card_id)}</th><td>${inspect('question',r.question_id,K().questions.find(q=>q.question_id===r.question_id)?.question||r.question_id)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div></details><details><summary>Sensitivity method and limitations</summary><p class="analysis-note">${esc(text(a.method))}</p><ul>${list(a.limitations).map(x=>`<li>${esc(text(x))}</li>`).join('')}</ul></details>${figuresView(a)}<div class="downloads"><a href="${esc(moduleFile('asr_sensitivity'))}" download>Recognizer-edition sensitivity JSON</a></div>`;}
function sensitivityNeighborView(a){const row=list(a.neighbors?.rows).find(x=>x.source_id===state.sensitivitySource);if(!row)return '<p class="empty">No source-neighbor comparison supplied.</p>';const cols=[['Original lexical',row.old_lexical_ids],['Counterfactual lexical',row.new_lexical_ids],['Original semantic',row.old_semantic_ids],['Counterfactual semantic',row.new_semantic_ids]];return `<p class="caption">This source text ${row.text_edition_changed?'was replaced in the sensitivity index':'was unchanged; its neighbors can still change when other sources change'}. Lexical Jaccard ${num(row.lexical_jaccard,3)} · semantic Jaccard ${num(row.semantic_jaccard,3)}.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Original and counterfactual source neighbors"><table class="comparison-table"><thead><tr><th>Rank</th>${cols.map(([title])=>`<th>${esc(title)}</th>`).join('')}</tr></thead><tbody>${Array.from({length:a.neighbors?.k||0},(_,i)=>`<tr><th scope="row">${i+1}</th>${cols.map(([,ids])=>`<td>${ids?.[i]?inspect('source',ids[i],source(ids[i])?.title||ids[i]):'Unavailable'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function facts(object){return `<dl class="fact-list">${Object.entries(object||{}).filter(([,v])=>typeof v!=='object'||v===null).map(([k,v])=>`<dt>${esc(human(k))}</dt><dd>${typeof v==='number'?num(v,4):v===null?'Unknown':esc(text(v))}</dd>`).join('')}</dl>`;}

function experimentsView(){
  const experimentModule=state.modules.experiments,rows=uniqueObjects([...list(A().hypotheses),...list(K().hypotheses),...list(experimentModule?.experiments||experimentModule?.hypotheses||experimentModule?.records||experimentModule)]),retrieval=state.modules.retrieval;
  return `<div class="scope-note"><p><strong>Source-card consolidation is a nonparametric experiment.</strong> It keeps evidence and citations outside the model. It does not reproduce Google's parameter expansion, weight updates or expert-routing “sleep” mechanism.</p></div>${retrieval?retrievalView(retrieval):unavailable('retrieval','The consolidation/retrieval diagnostic')}<h3>Hypotheses and experimental ledger</h3><div class="experiment-list">${rows.map((r,i)=>`<article class="experiment" data-experiment-id="${esc(r.id||r.hypothesis_id||`experiment-${i+1}`)}"><div>${badge(r.status||r.type||'proposed')}<span class="micro">${esc(r.id||r.hypothesis_id||`Experiment ${i+1}`)}</span></div><div><h3>${esc(r.title||r.question||r.hypothesis||'Research question')}</h3><p>${r.hypothesis||r.proposition?'<strong>Hypothesis:</strong> ':''}${esc(text(r.rationale||r.description||r.hypothesis||r.proposition||r.scope))}</p><dl><dt>Test / comparison</dt><dd>${esc(text(r.test||r.method||r.design||r.comparison||r.operationalization||'Not supplied'))}</dd><dt>${r.status==='proposed'?'Current scope':'Recorded observations'}</dt><dd>${list(r.observations).length?`<ul class="observations">${r.observations.map(x=>`<li>${esc(text(x))}</li>`).join('')}</ul>`:esc(text(r.result||r.results||r.finding||(r.result_reference?'Executed result fields: '+r.result_reference:'No executed result supplied')))}</dd><dt>Interpretation limit</dt><dd>${esc(text(r.limitation||r.limitations||r.limits||r.caveats||r.not_inferred||'See the protocol and source records.'))}</dd></dl>${r.execution_scope?`<p class="qualifier">${esc(r.execution_scope)}</p>`:''}${r.evidence_module&&state.manifest.modules[r.evidence_module]?`<p class="caption"><a href="${esc(moduleFile(r.evidence_module))}">Inspect ${esc(human(r.evidence_module))} evidence JSON</a></p>`:''}${r.cross_field_connection||r.field_connection?`<p class="caption">Methodological connection: ${esc(text(r.cross_field_connection||r.field_connection))}</p>`:''}${r.source_card_ids?`<p class="caption">Example source cards: ${r.source_card_ids.map(id=>inspect('card',id,id)).join(' · ')}</p>`:''}${r.source_ids?`<p class="caption">Sources: ${r.source_ids.map(id=>{const record=list(state.modules.literature?.records).find(x=>x.id===id);return record?external(record.url,record.title):source(id)?inspect('source',id,source(id).title):esc(id);}).join(' · ')}</p>`:''}</div></article>`).join('')||'<p class="empty">No hypothesis ledger is supplied. Empty results are not treated as confirmations.</p>'}</div>${crossFieldView(experimentModule)}`;
}
function uniqueObjects(rows){const seen=new Set();return rows.filter(r=>{if(!r||typeof r!=='object')return false;const k=r.id||r.hypothesis_id||JSON.stringify(r);if(seen.has(k))return false;seen.add(k);return true;});}
function retrievalView(r){const rows=list(r.summary),queries=list(r.queries);state.retrievalQuery ||= queries[0]?.query_id;const condition=id=>list(r.conditions).find(x=>x.id===id)?.label||human(id),bias=r.naive_fusion_coverage_bias||{};return `<h3>Source retrieval after consolidation</h3><p class="analysis-note">${esc(text(r.scope))}</p><p class="caption">${num(r.coverage?.queries)} source-informed queries · ${num(r.coverage?.sources)} source editions · ${num(r.coverage?.source_chunks)} raw chunks · ${num(r.coverage?.cards)} cards covering ${num(r.coverage?.card_sources)} sources.</p><div class="notice"><p>Questions were frozen before the card and ranking inspection, but authored after reading source evidence. These are known-support retrieval diagnostics, not held-out answer accuracy or evidence of model learning. Unjudged sources may also be relevant.</p><p>${esc(bias.interpretation||'Index coverage and source formats differ across conditions.')}</p>${bias.all_covered_sources_outrank_all_uncovered_by_construction?`<p>Naive full-list fusion: worst card-covered score ≥ ${num(bias.worst_covered_rrf_bound,5)}; best uncovered score ≤ ${num(bias.best_uncovered_rrf_bound,5)}. All covered sources outrank all uncovered sources by construction. The top-five candidate repair is explicitly post hoc.</p>`:''}</div><div class="table-wrap" tabindex="0" role="region" aria-label="Retrieval summary by model and condition"><table class="comparison-table"><thead><tr><th>Representation</th><th>Index / fusion condition</th><th>Known-support hit @1</th><th>Hit @3</th><th>Mean reciprocal rank</th><th>Known-support index coverage</th></tr></thead><tbody>${rows.map(x=>`<tr><th scope="row">${esc(x.model==='minilm'?'MiniLM':'TF-IDF')}</th><td>${esc(condition(x.condition))}</td><td>${num(x.known_support_hit_rate?.['1'],3)}</td><td>${num(x.known_support_hit_rate?.['3'],3)}</td><td>${num(x.mean_reciprocal_rank,3)}</td><td>${num(x.known_support_index_coverage,3)}</td></tr>`).join('')}</tbody></table></div><p class="analysis-note">Each aggregate has only ${num(r.coverage?.queries)} queries. Reciprocal rank is 1 divided by the first known-support source rank, with zero when absent. No generated answer or qualifier retention is scored.</p><div class="controls"><label>Inspect an audit query<select id="retrieval-query">${opt(queries.map(x=>x.query_id),state.retrievalQuery,id=>queries.find(x=>x.query_id===id)?.query||id)}</select></label></div><div id="retrieval-results">${retrievalQueryView(r)}</div><details><summary>Index sizes, coverage and protocol amendments</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Retrieval index coverage"><table><thead><tr><th>Index</th><th>Units</th><th>Sources</th><th>Words</th><th>UTF-8 bytes</th><th>Out-of-vocabulary term occurrences</th></tr></thead><tbody>${list(r.index_coverage).map(x=>`<tr><th scope="row">${esc(condition(x.condition))}</th><td>${num(x.units)}</td><td>${num(x.sources)}</td><td>${num(x.words)}</td><td>${num(x.utf8_bytes)}</td><td>${num(x.lexical_out_of_vocabulary_occurrences)}</td></tr>`).join('')}</tbody></table></div>${list(r.protocol_amendments).map(x=>`<p class="analysis-note"><strong>${esc(x.stage)}</strong> ${esc(x.reason)} ${esc(x.change)} ${esc(x.scope)}</p>`).join('')}<ul>${list(r.limitations).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>${figuresView(r)}<div class="downloads"><a href="${esc(moduleFile('retrieval'))}" download>Download complete retrieval results</a></div>`;}
function retrievalQueryView(r){const q=list(r.queries).find(x=>x.query_id===state.retrievalQuery);if(!q)return '<p class="empty">No query-level record supplied.</p>';const known=new Set(list(q.known_relevant_source_ids));return `<div class="scope-note"><p><strong>${esc(q.query)}</strong></p><p>${esc(q.rationale)}</p><p>Declared known support: ${list(q.known_relevant_source_ids).map(id=>inspect('source',id,source(id)?.title||id)).join(' · ')}</p><p>${esc(q.relevance_scope)}</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Per-query source rankings"><table class="comparison-table"><thead><tr><th>Representation / condition</th><th>First known-support rank</th><th>Hit @1 / @3 / @5</th><th>Top five source hits</th></tr></thead><tbody>${list(r.results).filter(x=>x.query_id===q.query_id).map(x=>`<tr><th scope="row">${esc(x.model==='minilm'?'MiniLM':'TF-IDF')}<small>${esc(list(r.conditions).find(c=>c.id===x.condition)?.label||human(x.condition))}</small></th><td>${x.first_known_support_rank===null?'Not retrieved':num(x.first_known_support_rank)}</td><td>${[1,3,5].map(k=>num(x.hit_at_k?.[String(k)])).join(' / ')}</td><td><ol>${list(x.ranked_sources).slice(0,5).map(hit=>`<li>${inspect('source',hit.source_id,source(hit.source_id)?.title||hit.source_id)}${known.has(hit.source_id)?' · Known support':' · Unjudged'}</li>`).join('')}</ol></td></tr>`).join('')}</tbody></table></div>`;}
function crossFieldView(x){const rows=list(x?.connections||x?.cross_field_connections||x?.analogies);if(!rows.length)return '';return `<h3>Connections to other research fields</h3><p class="analysis-note">These are methodological connections or hypotheses. They do not transfer empirical validation from another field to channeling claims.</p><div class="experiment-list">${rows.map(r=>`<article class="experiment"><div>${badge(r.relation||r.type||'analogy')}</div><div><h3>${esc(r.title||r.field)}</h3><p>${esc(text(r.connection||r.description||r.application))}</p><p class="qualifier">${esc(text(r.boundary||r.limitations||r.limitation))}</p></div></article>`).join('')}</div>`;}

function moduleFile(key){const v=state.manifest.modules[key];return safeFile(typeof v==='string'?v:v?.file)||'manifest.json';}
function sourcesView(){
  const l=state.modules.literature,records=list(l?.records),coverage=list(K().reading_coverage),artifacts=list(state.manifest.artifacts);
  return `<h3>Text editions in the fixed analysis frame</h3><div class="table-wrap" tabindex="0" role="region" aria-label="All modeled source editions"><table class="source-table"><thead><tr><th>Source number / title</th><th>Medium / printed label</th><th>Edition / words</th><th>Publisher</th></tr></thead><tbody>${documents().map((d,i)=>`<tr><th scope="row">${i+1}. ${inspect('source',d.source_id,d.title||d.source_id)}</th><td>${esc(medium(d))}<small>${esc(label(d))}</small></td><td>${esc(human(d.text_origin||d.document_kind||'Unreported'))}<small>${num(d.words)} words</small></td><td>${external(d.source_url||source(d.source_id)?.source_url,'Open source')}</td></tr>`).join('')}</tbody></table></div><h3>Actual reading coverage</h3><p class="analysis-note">Text included in a model is separate from text read to support answer cards. Coverage below is the declared unique inspected span union; it is not human annotation reliability. ${num(K().coverage?.unique_body_words_read)} unique body words were read across ${num(K().coverage?.read_sources)} sources, plus ${num(K().coverage?.documentary_question_words_read)} words in separate printed question fields. These are distinct from the ${num(A().totals?.words)} modeled body words.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Source reading coverage"><table class="source-table"><thead><tr><th>Source edition</th><th>Declared reading</th><th>Scope</th></tr></thead><tbody>${coverage.map(r=>`<tr><th scope="row">${inspect('source',r.source_id,source(r.source_id)?.title||r.source_id)}</th><td>${num(r.words_read??r.unique_words??r.inspected_words)} of ${num(r.source_words??source(r.source_id)?.words)} words<small>${num(r.spans?.length??r.unique_spans?.length??r.span_count)} spans</small></td><td>${esc(text(r.scope||r.selection_rule||r.coverage_status||r.reading_kind||(r.full_body_read===true?'Complete retained body read; AI annotation, no audio listening':r.full_body_read===false?'Selected bound spans; AI annotation, no audio listening':'See the source-bound coverage record.')))}</td></tr>`).join('')||'<tr><td colspan="3">No source-reading coverage records supplied.</td></tr>'}</tbody></table></div><h3>Research literature</h3>${l?`<p class="analysis-note">${esc(text(l.scope))}</p><div class="scope-note"><p>${esc(text(l.identification?.basis||l.identification))}</p></div><ul class="literature-list">${records.map(r=>`<li data-literature-id="${esc(r.id)}"><h3>${external(r.url,r.title)}</h3><p>${esc(text(r.application||r.claims_supported))}</p><p class="qualifier">${esc(text(r.limitations))}</p><small>${esc(text(r.authors))} · ${esc(r.year||r.published_at||'Date unreported')} · ${esc(r.version||'Version unreported')} · ${esc(human(r.access_depth||'Access depth unreported'))}</small><small>Inspected: ${esc(text(r.inspected_sections))} · Implementation: ${esc(human(r.implementation_status||'Not supplied'))}</small><span class="hash">Retained source SHA-256: ${esc(r.source_sha256||'Unreported')}</span></li>`).join('')}</ul>`:unavailable('literature','The research literature register')}<h3>Portable data and methods</h3><p class="analysis-note">Public downloads contain source metadata, measured results and labeled paraphrases. Full audio, complete third-party text, exact private evidence slices and model weights are kept outside this site.</p><div class="downloads">${Object.entries(state.manifest.modules).filter(([key])=>state.modules[key]).map(([key])=>`<a href="${esc(moduleFile(key))}" download>${esc(human(key))} JSON</a>`).join('')}<a href="manifest.json" download>Release manifest</a></div>${artifacts.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Release artifact downloads"><table class="file-table"><thead><tr><th>Artifact</th><th>Size / integrity</th></tr></thead><tbody>${artifacts.filter(a=>safeFile(a.file)).map(a=>`<tr><th scope="row"><a href="${esc(a.file)}" download>${esc(a.label||a.file)}</a></th><td>${num(a.bytes)} bytes<span class="hash">${esc(a.sha256||'Hash unreported')}</span></td></tr>`).join('')}</tbody></table></div>`:''}<details><summary>Study limitations</summary><ul>${unique([...list(A().limitations),...list(K().limitations)]).map(x=>`<li>${esc(text(x))}</li>`).join('')}</ul></details>`;
}

function supportView(s){return `<li>Characters ${num(s.start_character)}–${num(s.end_character)} (end exclusive) · ${num(s.words)} span words${finite(s.start_seconds)&&finite(s.end_seconds)?`<small>ASR seconds ${num(s.start_seconds,2)}–${num(s.end_seconds,2)}; alignment unverified.</small>`:''}${list(s.turn_ids).length?`<small>Turns: ${esc(s.turn_ids.join(', '))}</small>`:''}<span class="hash">Source text: ${esc(s.text_artifact_sha256||s.body_sha256||'Unreported')}</span><span class="hash">Span: ${esc(s.span_sha256||'Unreported')}</span></li>`;}
function openInspector(kind,id,trigger){
  if(!$('#inspector').open)state.trigger=trigger||document.activeElement;let title=id,body='';
  if(kind==='source'){
    const d={...(doc(id)||{}),...(source(id)||{})};title=d.title||id;body=`<p>${external(d.source_url,'Publisher source')}</p><dl class="fact-list"><dt>Source ID</dt><dd>${esc(id)}</dd><dt>Medium context</dt><dd>${esc(medium(d))}</dd><dt>Printed claim label</dt><dd>${esc(label(d))}</dd><dt>Text origin</dt><dd>${esc(human(d.text_origin||d.document_kind))}</dd><dt>Publication date</dt><dd>${esc(d.published_at||d.date||'Unreported')}</dd><dt>Words</dt><dd>${num(d.words)}</dd><dt>Attribution scope</dt><dd>${esc(text(d.attribution_scope||d.qualifying_note||'Source-level attribution, not authenticated entity identity.'))}</dd><dt>Speaker status</dt><dd>${esc(text(d.speaker_role||d.speaker_roles||'Unknown unless the publisher explicitly prints a role.'))}</dd></dl><span class="hash">Text artifact SHA-256: ${esc(d.text_artifact_sha256||d.text_sha256||'Unreported')}</span>${d.body_sha256?`<span class="hash">Normalized body SHA-256: ${esc(d.body_sha256)}</span>`:''}<p class="source-note">A source's attributed name does not assign every host, narrator or unknown ASR utterance to that speaker. Text recognition and audio alignment remain unverified unless explicitly documented.</p>`;
  }else if(kind==='question'){
    const q=K().questions.find(x=>x.question_id===id);if(!q)return;title=q.question;body=`${badge(q.question_type)}<p class="source-note">${esc(q.selection_basis||'Selection basis unreported')}</p><dl class="fact-list"><dt>Question ID</dt><dd>${esc(q.question_id)}</dd><dt>Topic</dt><dd>${esc(q.topic_id)}</dd><dt>Source answers visible</dt><dd>${q.informed_by_answer_reading===true?'Yes; in-sample diagnostic':q.informed_by_answer_reading===false?'No, as declared':'Unreported'}</dd></dl><p>${esc(q.question_type==='documentary_printed_paraphrase'?'This wording is a paraphrase of a publisher-printed question, not a verbatim transcript quotation.':'This is an analyst-constructed comparison question, not a claim that every source was asked these words.')}</p>${q.supports?`<ul class="citation-list">${list(q.supports).map(supportView).join('')}</ul>`:''}<h3>Associated answer cards</h3>${cardsFor(id).map(cardView).join('')}`;
  }else if(kind==='card'){
    const c=K().cards.find(x=>x.card_id===id);if(!c)return;title='Source answer card';body=`<p>${esc(c.paraphrase)}</p><p class="qualifier">${esc(c.qualifying_note||'No further qualification supplied.')}</p><dl class="fact-list"><dt>Card ID</dt><dd>${esc(c.card_id)}</dd><dt>Source</dt><dd>${inspect('source',c.source_id,source(c.source_id)?.title||c.source_id)}</dd><dt>Claim type</dt><dd>${esc(human(c.claim_type))}</dd><dt>Conditions</dt><dd>${esc(text(c.conditions)||'Unreported')}</dd><dt>Time scope</dt><dd>${esc(text(c.time_scope)||'Unreported')}</dd><dt>Annotation provenance</dt><dd>${esc(text(c.annotation))}</dd></dl><h3>Bound source spans</h3><ul class="citation-list">${list(c.supports).map(supportView).join('')}</ul><p class="source-note">Evidence slices remain private. The visible answer is a labeled paraphrase, not documentary wording or verified advice.</p>`;
  }else if(kind==='comparison'){
    const c=list(K().comparisons).find(x=>x.comparison_id===id);if(!c)return;title=relations[c.relation]||human(c.relation);body=`${comparisonView(c)}<dl class="fact-list"><dt>Matching context</dt><dd>${esc(text(c.matching_context))}</dd><dt>Source-label scope</dt><dd>${esc(text(c.source_label_scope||c.label_scope||'No shared entity identity inferred'))}</dd></dl><div class="answer-grid">${[c.left_card_id,c.right_card_id].map(x=>K().cards.find(a=>a.card_id===x)).filter(Boolean).map(cardView).join('')}</div>`;
  }else if(kind==='graph'){
    const n=graphNodes().find(x=>nodeId(x)===id);if(!n)return;const kind=nodeType(n),entity=n.entity_id||n[kind+'_id']||(['question','card','comparison'].includes(kind)?nodeId(n):null);if(entity&&['source','question','card','comparison'].includes(kind)){openInspector(kind,entity,trigger);return;}title=n.label||n.title||id;body=`${badge(kind)}<p class="source-note">${esc(text(n.scope||n.qualification||n.description||'A typed record in the knowledge graph; node grouping does not authenticate an entity.'))}</p><dl class="fact-list">${Object.entries(n).filter(([k,v])=>!['label','title'].includes(k)&&typeof v!=='object').map(([k,v])=>`<dt>${esc(human(k))}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;
  }
  $('#inspector-body').innerHTML=`<h2 id="inspector-title">${esc(title)}</h2>${body}`;if(!$('#inspector').open)$('#inspector').showModal();$('#close-inspector').focus();
}
function csvValue(value){let v=value===null||value===undefined?'':String(value);if(/^[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}
function downloadCSV(name,headers,rows){const raw=[headers,...rows].map(r=>r.map(csvValue).join(',')).join('\r\n')+'\r\n',blob=new Blob([raw],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce(`Downloaded ${rows.length} rows in ${name}.`);}
function bindControls(){
  $('#contextual-term')?.addEventListener('change',e=>{state.contextualTerm=e.target.value;$('#contextual-results').innerHTML=contextualTermResults(state.modules.contextual_terms);});
  $('#sensitivity-source')?.addEventListener('change',e=>{state.sensitivitySource=e.target.value;$('#sensitivity-neighbors').innerHTML=sensitivityNeighborView(state.modules.asr_sensitivity);});
  $('#asr-context')?.addEventListener('change',e=>{state.asrContext=e.target.value;$('#asr-window-results').innerHTML=asrWindowsView(state.modules.asr);});
  $('#retrieval-query')?.addEventListener('change',e=>{state.retrievalQuery=e.target.value;$('#retrieval-results').innerHTML=retrievalQueryView(state.modules.retrieval);});
  $('#question-query').addEventListener('input',e=>{state.query=e.target.value;state.page=1;updateQuestions();});
  for(const[id,key]of [['question-topic','topic'],['question-relation','relation'],['question-medium','medium'],['question-type','questionType']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;state.page=1;updateQuestions();});
  $('#clear-questions').addEventListener('click',()=>{state.query='';state.topic=state.relation=state.medium=state.questionType='all';state.page=1;$('#question-query').value='';for(const id of ['question-topic','question-relation','question-medium','question-type'])$('#'+id).value='all';updateQuestions();});
  $('#export-questions').addEventListener('click',()=>downloadCSV('knowledge-questions.csv',['question_id','question_type','topic_id','question','selection_basis','informed_by_answer_reading','answer_cards','comparisons'],K().questions.map(q=>[q.question_id,q.question_type,q.topic_id,q.question,q.selection_basis,q.informed_by_answer_reading,cardsFor(q.question_id).length,comparisonsFor(q.question_id).length])));
  for(const[id,key]of [['graph-question','graphQuestion'],['graph-edge','graphEdge']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;$('#graph-results').innerHTML=graphView();});
  $('#export-edges').addEventListener('click',()=>downloadCSV('knowledge-edges.csv',['source','relation','target','qualification'],graphEdges().map(e=>[e.from,e.type,e.to,e.qualification||e.scope||e.note||''])));
  for(const[id,key]of [['projection-mode','representation'],['projection-color','color']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;$('#projection-results').innerHTML=projectionView();});
  $('#projection-labels').addEventListener('change',e=>{state.labels=e.target.value==='on';$('#projection-results').innerHTML=projectionView();});
  $('#neighbor-source').addEventListener('change',e=>{state.neighborSource=e.target.value;$('#neighbor-results').innerHTML=neighborView();});
  $('#export-neighbors').addEventListener('click',()=>downloadCSV('knowledge-neighbor-comparison.csv',['source_id','lexical_neighbors','semantic_neighbors','window_neighbors','lexical_semantic_jaccard','semantic_window_jaccard'],list(A().neighbors?.rows).map(r=>[r.source_id,list(r.lexical_ids).join(' | '),list(r.semantic_ids).join(' | '),list(r.window_ids).join(' | '),r.jaccard,r.window_jaccard])));
  $('#pair-order').addEventListener('change',e=>{state.matrixMode=e.target.value;$('#pair-results').innerHTML=pairView();});
  $('#export-pairs').addEventListener('click',()=>downloadCSV('knowledge-all-source-pairs.csv',['source','target','same_medium','same_comparison_label','lexical_cosine','semantic_cosine','window_lexical_cosine','window_semantic_cosine'],list(A().pairs).map(r=>[r.source,r.target,r.same_medium,r.same_label,r.lexical_cosine,r.semantic_cosine,r.window_lexical_cosine,r.window_semantic_cosine])));
}
document.addEventListener('click',e=>{
  const term=e.target.closest('[data-context-term]');if(term){state.contextualTerm=term.dataset.contextTerm;$('#contextual-term').value=state.contextualTerm;$('#contextual-results').innerHTML=contextualTermResults(state.modules.contextual_terms);$('#contextual-term').focus({preventScroll:true});announce('Selected contextual term '+state.contextualTerm);return;}
  const action=e.target.closest('[data-inspect-kind]');if(action){openInspector(action.dataset.inspectKind,action.dataset.inspectId,action);return;}
  const page=e.target.closest('[data-question-page]');if(page){state.page=Number(page.dataset.questionPage);updateQuestions();return;}
  const node=e.target.closest('[data-graph-node]');if(node){openInspector('graph',node.dataset.graphNode,node);return;}
  const point=e.target.closest('[data-point]');if(point){state.selectedSource=point.dataset.point;state.neighborSource=state.selectedSource;$('#neighbor-source').value=state.neighborSource;$('#neighbor-results').innerHTML=neighborView();$('#selected-source-summary').innerHTML=`<p class="scope-note">Selected source: ${inspect('source',state.selectedSource,doc(state.selectedSource)?.title||state.selectedSource)}. Its nearest neighbors are shown below.</p>`;document.querySelectorAll('[data-point]').forEach(x=>x.classList.toggle('is-selected',x.dataset.point===state.selectedSource));if(state.labels){const focused=document.activeElement===point,index=[...document.querySelectorAll('[data-point]')].indexOf(point);$('#projection-results').innerHTML=projectionView();if(focused)document.querySelectorAll('[data-point]')[index]?.focus({preventScroll:true});}announce('Selected '+(doc(state.selectedSource)?.title||state.selectedSource));}
});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-graph-node],[data-point],[data-context-term]:not(button),[data-context-source]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#close-inspector').addEventListener('click',()=>$('#inspector').close());
$('#inspector').addEventListener('close',()=>{if(state.trigger?.isConnected&&!$('#inspector').contains(state.trigger))state.trigger.focus();});
load();

function highlightGraph(id){const linked=new Set([id]);graphEdges().forEach(e=>{if(e.from===id)linked.add(e.to);if(e.to===id)linked.add(e.from);});document.querySelectorAll('[data-graph-node]').forEach(n=>n.classList.toggle('is-dim',Boolean(id)&&!linked.has(n.dataset.graphNode)));document.querySelectorAll('.graph-edge').forEach(e=>e.classList.toggle('is-dim',Boolean(id)&&e.dataset.from!==id&&e.dataset.to!==id));}
document.addEventListener('pointerover',e=>{const n=e.target.closest('[data-graph-node]');if(n)highlightGraph(n.dataset.graphNode);});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-graph-node]'))highlightGraph(null);});
document.addEventListener('focusin',e=>{const n=e.target.closest('[data-graph-node]');if(n)highlightGraph(n.dataset.graphNode);});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-graph-node]'))highlightGraph(null);});
